    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    wall = min(counts, key=counts.get)
    background = max(counts, key=counts.get)

    outside = set()
    stack = []
    for r in range(h):
        for c in range(w):
            if (r == 0 or r == h - 1 or c == 0 or c == w - 1) and grid[r][c] == background:
                stack.append((r, c))

    while stack:
        r, c = stack.pop()
        if (r, c) in outside:
            continue
        outside.add((r, c))
        for nr, nc in ((r-1, c), (r+1, c), (r, c-1), (r, c+1)):
            if (0 <= nr < h and 0 <= nc < w and
                    grid[nr][nc] == background and (nr, nc) not in outside):
                stack.append((nr, nc))

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background and (r, c) not in outside:
                out[r][c] = 4
    return out
